INSERT INTO public.announcements VALUES (1, 'October monitoring window is now open', 'All schools must submit their October enrollment and compliance updates through the district dashboard before October 25, 2026. School heads may coordinate with their district administrator for corrections.', 1, NULL, '2026-10-01 08:00:00+08', 'published', '2026-10-26 21:32:13.985614+08', '2026-10-26 21:32:13.985614+08');
INSERT INTO public.announcements VALUES (3, 'District performance review schedule', 'The quarterly performance review will take place on November 6, 2026. District administrators will receive a consolidated school comparison report two days before the session.', 1, NULL, '2026-10-12 09:30:00+08', 'published', '2026-10-26 21:32:13.985614+08', '2026-10-26 21:32:13.985614+08');
INSERT INTO public.announcements VALUES (4, 'Reminder: keep school contact details current', 'Please review each school record and update the school head, email address, and contact number when assignments change. Accurate contact details help the district office follow up on pending reports.', 1, NULL, '2026-10-20 07:45:00+08', 'published', '2026-10-26 21:32:13.985614+08', '2026-10-26 21:32:13.985614+08');
INSERT INTO public.announcements VALUES (2, 'North Valley planning session (draft)', 'The North Valley district office is preparing its 2027 school improvement planning session. This announcement is still in draft and is visible only to district administrators.', 1, 19, NULL, 'draft', '2026-10-26 21:32:13.985614+08', '2026-10-28 15:58:33.493767+08');


